import csv
from .export import iter_export_rows
def run(path='data/probes.csv'):
    with open(path, newline='') as stream:
        records = list(csv.DictReader(stream))
    return ''.join(iter_export_rows(records))
if __name__ == '__main__':
    print(run(), end='')

