import csv
from io import StringIO
def encode_latency_row(tunnel, milliseconds):
    buffer = StringIO(newline='')
    csv.writer(buffer, lineterminator='\n').writerow([tunnel, milliseconds])
    return buffer.getvalue()
def format_latency_label(milliseconds):
    return f'{milliseconds} ms'
